        Object.assign(win.style, { left: left + 'px', top: top + 'px', width: Math.max(320, innerWidth - left) + 'px', height: Math.max(200, innerHeight - top) + 'px', maxWidth: 'none', maxHeight: 'none', resize: 'none' });
